package raccoon

// This file implements Office Raccoon's web authorization login (/code/authorize authorization page + callback link pasting).
//
// Workflow (consistent with Agent2API's web authorization login):
//
//  1. LoginStart generates a one-time state (64-bit lowercase hex) and returns the official authorization page URL:
//     {origin}/code/authorize?login_source=desktop&appname=…&state=<state>
//  2. The user logs in on the official page (WeChat/verification code/password are all supported);
//  3. The official page redirects to the custom protocol office-raccoon://auth/callback?code=…&state=…
//     (It is normal if the browser cannot open this protocol—keep the entire link in the address bar);
//  4. The user pastes the entire callback link back into the console, and SubmitCallback exchanges the code for a ticket to complete login.
//
// Note: The early WeChat QR code channel in the panel project (/login/mp hosting page +
// login_with_qrcode_code polling) has become unavailable as upstream pages have been deprecated (observed 404,
// 2024-10-24), so this implementation only retains the authorization page channel.
//
// Security semantics of state (same specification as Agent2API): generated by the plugin, registered into the shared session table
// (with TTL and polling throttling); state in the callback must match character by character and is one-time use.

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"

	"free-model-hub/internal/core"
	"free-model-hub/internal/hostbridge"
)

// loginAppName is the client name reported on the authorization page (consistent with the official desktop client).
const loginAppName = "办公小浣熊客户端"

// loginCallbackScheme / Host / Path are the fixed structure of the official client callback.
const (
	loginCallbackScheme = "office-raccoon"
	loginCallbackHost   = "auth"
	loginCallbackPath   = "/callback"
)

// qrLoginTTL and qrPollInterval are the login session validity period and polling throttling.
const (
	qrLoginTTL     = 15 * time.Minute
	qrPollInterval = 2 * time.Second
)

// PendingLogin is an ongoing login session data structure.
//
// TTL and polling throttling are centrally managed by the session table in internal/auth, leaving only protocol state here.
type PendingLogin struct {
	State string
}

// StoreLoginSession registers an ongoing login session.
func StoreLoginSession(logins core.LoginSessions, sessionID string, session *PendingLogin) {
	if session == nil {
		return
	}
	logins.Register(VendorID, sessionID, qrLoginTTL, qrPollInterval, session)
}

// RemoveLoginSession clears the session after successful login or termination.
func RemoveLoginSession(logins core.LoginSessions, sessionID string) {
	logins.Delete(sessionID)
}

// CheckLoginSession checks the login session status and throttling.
// Returns (session, exists, shouldPoll).
func CheckLoginSession(logins core.LoginSessions, sessionID string) (*PendingLogin, bool, bool) {
	entry, pollState := logins.Poll(sessionID)
	if pollState == core.PollMissing {
		return nil, false, false
	}
	pending, okPending := entry.Data.(*PendingLogin)
	if !okPending {
		return nil, false, false
	}
	return pending, true, pollState == core.PollReady
}

// pendingMessage is the progress text displayed during polling waiting (telling the user what to do next).
const pendingMessage = "Waiting for the user to complete login on the authorization page... After successful login, the browser will redirect to a link starting with office-raccoon://, " +
	"please copy the entire link from the address bar back to the console to complete login"

// CheckCallbackState validates that the state in the callback link matches the current session (exact character comparison).
func CheckCallbackState(session *PendingLogin, callbackState string) bool {
	return session != nil && strings.TrimSpace(callbackState) == session.State
}

// ErrCodeExpired is the upstream business code for "authorization code expired" (200035): not that the login service
// is broken, but the user kept the callback link too long or clicked repeatedly, so the message must prompt to restart.
const ErrCodeExpired = 200035

// ExchangeAuthorizationCode exchanges a one-time authorization code for credentials
// (POST {auth_base}/login_with_authorization_code).
func ExchangeAuthorizationCode(ctx context.Context, authBase, code string) (access, refresh string, expiresAt int64, uid string, err error) {
	if strings.TrimSpace(authBase) == "" {
		return "", "", 0, "", fmt.Errorf("upstream auth base URL is not configured")
	}
	body, errMarshal := json.Marshal(map[string]string{"authorization_code": code})
	if errMarshal != nil {
		return "", "", 0, "", fmt.Errorf("marshal exchange request: %w", errMarshal)
	}
	req, errReq := http.NewRequestWithContext(ctx, http.MethodPost, authBase+LoginCodePath, strings.NewReader(string(body)))
	if errReq != nil {
		return "", "", 0, "", fmt.Errorf("build exchange request: %w", errReq)
	}
	ApplyAPIHeaders(req, "")
	req.Header.Set("Content-Type", "application/json")

	resp, errDo := hostbridge.Client(ctx, apiHTTPTimeout).Do(req)
	if errDo != nil {
		return "", "", 0, "", &core.Failure{Msg: "exchange: " + errDo.Error(), Kind: core.FailureKindTransient}
	}
	defer func() { _ = resp.Body.Close() }()

	raw, errRead := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
	if errRead != nil {
		return "", "", 0, "", &core.Failure{Status: resp.StatusCode, Msg: "read exchange response: " + errRead.Error(), Kind: core.FailureKindTransient}
	}
	var envelope struct {
		Code    *int64          `json:"code"`
		Message string          `json:"message"`
		Msg     string          `json:"msg"`
		Details string          `json:"details"`
		Data    json.RawMessage `json:"data"`
	}
	if errUnmarshal := json.Unmarshal(raw, &envelope); errUnmarshal != nil {
		return "", "", 0, "", Classify(resp.StatusCode, string(raw))
	}
	errMsg := core.FirstNonEmpty(envelope.Message, envelope.Msg, envelope.Details)
	if envelope.Code != nil {
		if *envelope.Code == ErrCodeExpired || strings.Contains(errMsg, "authorization_code_not_found") {
			return "", "", 0, "", &core.Failure{Status: resp.StatusCode, Msg: "Authorization code has expired or does not exist, please re-initiate login", Kind: core.FailureKindClient}
		}
		if *envelope.Code != 0 {
			return "", "", 0, "", ClassifyBusiness(resp.StatusCode, *envelope.Code, errMsg)
		}
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return "", "", 0, "", Classify(resp.StatusCode, string(raw))
	}
	var data struct {
		AccessToken  string `json:"access_token"`
		RefreshToken string `json:"refresh_token"`
		ExpiresAt    any    `json:"expires_at"`
		UserID       string `json:"user_id"`
	}
	if len(envelope.Data) > 0 && string(envelope.Data) != "null" {
		if errUnmarshal := json.Unmarshal(envelope.Data, &data); errUnmarshal != nil {
			return "", "", 0, "", fmt.Errorf("parse exchange data: %w", errUnmarshal)
		}
	}
	access = strings.TrimSpace(data.AccessToken)
	refresh = strings.TrimSpace(data.RefreshToken)
	if access == "" || refresh == "" {
		return "", "", 0, "", &core.Failure{Status: resp.StatusCode, Msg: "Office Raccoon did not return complete credentials (access_token/refresh_token)", Kind: core.FailureKindServer}
	}
	if ms := core.GetUnixSeconds(map[string]any{"expires_at": data.ExpiresAt}, "expires_at"); ms > 0 {
		expiresAt = ms
	}
	uid = strings.TrimSpace(data.UserID)
	return access, refresh, expiresAt, uid, nil
}

// ParseCallbackCode extracts the authorization code and state from the callback link.
//
// Only recognizes the fixed structure of the official client callback office-raccoon://auth/callback?code=…&state=…
// (Agent2API oauth.rs same specification): scheme/host/path compared item by item, avoiding prefix matching—
// structures like office-raccoon://auth/callback@evil.com would all be allowed by startsWith.
// The callback lands on a custom protocol, and any local program can construct one and throw it into the login window. Failing to validate the state
// is equivalent to wide open to "writing credentials obtained using someone else's code into your account database".
func ParseCallbackCode(raw string) (code, state string, ok bool) {
	raw = strings.TrimSpace(raw)
	if index := strings.IndexAny(raw, "\r\n"); index >= 0 {
		raw = raw[:index]
	}
	parsed, errParse := url.Parse(raw)
	if errParse != nil {
		return "", "", false
	}
	if !strings.EqualFold(parsed.Scheme, loginCallbackScheme) ||
		!strings.EqualFold(parsed.Host, loginCallbackHost) ||
		parsed.Path != loginCallbackPath {
		return "", "", false
	}
	query := parsed.Query()
	code = strings.TrimSpace(query.Get("code"))
	if code == "" {
		code = strings.TrimSpace(query.Get("authorization_code"))
	}
	return code, query.Get("state"), code != ""
}

// AuthorizeURLWith constructs the official authorization page URL (panel's AuthorizeURL specification:
// login_source=desktop & client=desktop & app_name=<Chinese client name>).
func AuthorizeURLWith(origin, appName, state string) string {
	query := url.Values{}
	query.Set("login_source", "desktop")
	query.Set("client", "desktop")
	query.Set("app_name", appName)
	if strings.TrimSpace(state) != "" {
		query.Set("state", state)
	}
	return strings.TrimRight(origin, "/") + AuthorizePath + "?" + query.Encode()
}
